parameters.query:
let firstSignIn = toscalar(customEvents | where name == "CAMS Sign-In" | summarize min(timestamp));
let rangeStart = todatetime("{TimeRange:start}");
print Note = case(
    isnull(firstSignIn), "No sign-in data has been recorded yet, so the list is empty.",
    rangeStart < startofday(firstSignIn), strcat("The chosen range starts before the earliest sign-in data still kept (", format_datetime(firstSignIn, "yyyy-MM-dd"), "). The list covers ", format_datetime(firstSignIn, "yyyy-MM-dd"), " onward."),
    strcat("Earliest sign-in data still kept: ", format_datetime(firstSignIn, "yyyy-MM-dd"), ". The chosen range is fully covered.")
)
